package com.behsazan.corebanking.posting.configuration;

import com.behsazan.corebanking.posting.readiness.PostingReadinessCatalog;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Map;

/**
 * Whitelisted, parameterized Oracle SELECTs; no user-controlled identifiers.
 * Results are capped at 51. The resolver FAILS on 51 rather than silently
 * ignoring later candidates. UTC text explicitly normalizes Oracle TSTZ.
 */
@Repository
@ConditionalOnProperty(prefix = "core-banking.deal-posting.readiness", name = "enabled", havingValue = "true")
public class OraclePostingConfigurationRepository implements PostingConfigurationRepository {
    private static final String UTC_FROM = "TO_CHAR(EFFECTIVE_FROM AT TIME ZONE 'UTC', 'YYYY-MM-DD\"T\"HH24:MI:SS.FF6\"Z\"', 'NLS_CALENDAR=GREGORIAN') AS FROM_UTC";
    private static final String UTC_UNTIL = "TO_CHAR(EFFECTIVE_UNTIL AT TIME ZONE 'UTC', 'YYYY-MM-DD\"T\"HH24:MI:SS.FF6\"Z\"', 'NLS_CALENDAR=GREGORIAN') AS UNTIL_UTC";
    private static final String UTC_DECIDED = "TO_CHAR(DECIDED_AT AT TIME ZONE 'UTC', 'YYYY-MM-DD\"T\"HH24:MI:SS.FF6\"Z\"', 'NLS_CALENDAR=GREGORIAN') AS DECIDED_UTC";
    private static final String DATE_START = "TO_CHAR(PERIOD_START, 'YYYY-MM-DD', 'NLS_CALENDAR=GREGORIAN') AS START_DATE";
    private static final String DATE_END = "TO_CHAR(PERIOD_END, 'YYYY-MM-DD', 'NLS_CALENDAR=GREGORIAN') AS END_DATE";

    private static final Map<String, String> QUERIES = Map.ofEntries(
            Map.entry("ASSET", "SELECT IDENTIFIER, ASSET_CODE, DECIMAL_PRECISION, ASSET_STATE FROM LGR.ASSETS WHERE ASSET_CODE = :assetCode ORDER BY IDENTIFIER FETCH FIRST 51 ROWS ONLY"),
            Map.entry("BOOK", "SELECT IDENTIFIER, BOOK_CODE, LEGAL_ENTITY_REFERENCE, BASE_CURRENCY_CODE, BOOK_STATE FROM ACC.ACCOUNTING_BOOKS WHERE BOOK_CODE = :bookCode AND LEGAL_ENTITY_REFERENCE = :legalEntityReference ORDER BY IDENTIFIER FETCH FIRST 51 ROWS ONLY"),
            Map.entry("PERIOD", "SELECT IDENTIFIER, ACCOUNTING_BOOK_IDENTIFIER, PERIOD_CODE, PERIOD_STATE, " + DATE_START + ", " + DATE_END + " FROM ACC.FISCAL_PERIODS WHERE ACCOUNTING_BOOK_IDENTIFIER = :bookId ORDER BY IDENTIFIER FETCH FIRST 51 ROWS ONLY"),
            Map.entry("RULE", "SELECT V.IDENTIFIER, V.POSTING_RULE_IDENTIFIER, V.VERSION_NUMBER, V.PUBLICATION_STATE, V.APPROVAL_REFERENCE, V.CONTENT_HASH, " +
                    "TO_CHAR(V.EFFECTIVE_FROM AT TIME ZONE 'UTC', 'YYYY-MM-DD\"T\"HH24:MI:SS.FF6\"Z\"', 'NLS_CALENDAR=GREGORIAN') AS FROM_UTC, " +
                    "TO_CHAR(V.EFFECTIVE_UNTIL AT TIME ZONE 'UTC', 'YYYY-MM-DD\"T\"HH24:MI:SS.FF6\"Z\"', 'NLS_CALENDAR=GREGORIAN') AS UNTIL_UTC " +
                    "FROM PST.POSTING_RULES R JOIN PST.POSTING_RULE_VERSIONS V ON V.POSTING_RULE_IDENTIFIER = R.IDENTIFIER " +
                    "WHERE R.RULE_CODE = :ruleCode ORDER BY V.IDENTIFIER FETCH FIRST 51 ROWS ONLY"),
            Map.entry("CONDITIONS", "SELECT IDENTIFIER, CONDITION_SEQUENCE, ATTRIBUTE_NAME, COMPARISON_OPERATOR, EXPECTED_VALUE FROM PST.POSTING_RULE_CONDITIONS WHERE POSTING_RULE_VERSION_IDENTIFIER = :ruleId ORDER BY CONDITION_SEQUENCE, IDENTIFIER FETCH FIRST 51 ROWS ONLY"),
            Map.entry("ASSIGNMENT", "SELECT IDENTIFIER, POSTING_RULE_VERSION_IDENTIFIER, POSTING_TEMPLATE_VERSION_IDENTIFIER, ACCOUNTING_PURPOSE, PUBLICATION_STATE, APPROVAL_REFERENCE, CONTENT_HASH, " + UTC_FROM + ", " + UTC_UNTIL + " FROM PST.POSTING_RULE_TEMPLATE_ASSIGNMENTS WHERE POSTING_RULE_VERSION_IDENTIFIER = :ruleId AND ACCOUNTING_PURPOSE = :accountingPurpose ORDER BY IDENTIFIER FETCH FIRST 51 ROWS ONLY"),
            Map.entry("TEMPLATE", "SELECT IDENTIFIER, POSTING_TEMPLATE_IDENTIFIER, VERSION_NUMBER, PUBLICATION_STATE, CONTENT_HASH, " + UTC_FROM + ", " + UTC_UNTIL + " FROM PST.POSTING_TEMPLATE_VERSIONS WHERE IDENTIFIER = :templateId ORDER BY IDENTIFIER FETCH FIRST 51 ROWS ONLY"),
            Map.entry("TEMPLATE_APPROVAL", "SELECT IDENTIFIER, SUBJECT_REFERENCE, APPROVAL_TYPE, REQUESTED_BY, APPROVED_BY, DECISION_STATE, " + UTC_DECIDED + " FROM PST.POSTING_APPROVALS WHERE SUBJECT_REFERENCE = :subjectReference AND APPROVAL_TYPE = 'PUBLISH' ORDER BY IDENTIFIER FETCH FIRST 51 ROWS ONLY"),
            Map.entry("TEMPLATE_LINES", "SELECT IDENTIFIER, SEQUENCE_NUMBER, SOURCE_ACCOUNT_ROLE, DESTINATION_ACCOUNT_ROLE, AMOUNT_COMPONENT, ASSET_POLICY FROM PST.POSTING_TEMPLATE_LINES WHERE POSTING_TEMPLATE_VERSION_IDENTIFIER = :templateId ORDER BY SEQUENCE_NUMBER, IDENTIFIER FETCH FIRST 51 ROWS ONLY"),
            Map.entry("MAPPING", "SELECT IDENTIFIER, MAPPING_CODE, VERSION_NUMBER, PUBLICATION_STATE, APPROVAL_REFERENCE, CONTENT_HASH, " + UTC_FROM + ", " + UTC_UNTIL + " FROM ACC.ACCOUNTING_MAPPING_VERSIONS WHERE MAPPING_CODE = :mappingCode ORDER BY IDENTIFIER FETCH FIRST 51 ROWS ONLY"),
            Map.entry("MAPPING_ENTRIES", "SELECT IDENTIFIER, SEQUENCE_NUMBER, SOURCE_EVENT_TYPE, ACCOUNTING_COMPONENT, ACCOUNT_ROLE, POSTING_DIRECTION, DIMENSION_POLICY FROM ACC.ACCOUNTING_MAPPING_ENTRIES WHERE ACCOUNTING_MAPPING_VERSION_IDENTIFIER = :mappingId AND SOURCE_EVENT_TYPE = :eventType ORDER BY SEQUENCE_NUMBER, IDENTIFIER FETCH FIRST 51 ROWS ONLY"),
            Map.entry("CHART", "SELECT IDENTIFIER, ACCOUNTING_BOOK_IDENTIFIER, CHART_CODE, " + UTC_FROM + ", " + UTC_UNTIL + " FROM ACC.CHARTS_OF_ACCOUNTS WHERE ACCOUNTING_BOOK_IDENTIFIER = :bookId AND CHART_CODE = :chartCode ORDER BY IDENTIFIER FETCH FIRST 51 ROWS ONLY"),
            Map.entry("ROLE_ASSIGNMENT", "SELECT IDENTIFIER, ACCOUNTING_MAPPING_VERSION_IDENTIFIER, ACCOUNTING_BOOK_IDENTIFIER, GENERAL_LEDGER_ACCOUNT_IDENTIFIER, ACCOUNT_ROLE, CURRENCY_CODE, PRODUCT_VERSION_REFERENCE, BANK_UNIT_REFERENCE, PUBLICATION_STATE, APPROVAL_REFERENCE, CONTENT_HASH, " + UTC_FROM + ", " + UTC_UNTIL + " FROM ACC.ACCOUNT_ROLE_ASSIGNMENTS WHERE ACCOUNTING_MAPPING_VERSION_IDENTIFIER = :mappingId AND ACCOUNTING_BOOK_IDENTIFIER = :bookId AND CURRENCY_CODE = :currencyCode AND PRODUCT_VERSION_REFERENCE = :productVersionReference AND BANK_UNIT_REFERENCE = :bankUnitReference ORDER BY IDENTIFIER FETCH FIRST 51 ROWS ONLY"),
            Map.entry("GL", "SELECT IDENTIFIER, CHART_OF_ACCOUNTS_IDENTIFIER, ACCOUNT_CODE, ACCOUNT_STATE, ACCOUNT_TYPE, NORMAL_BALANCE_DIRECTION FROM ACC.GENERAL_LEDGER_ACCOUNTS WHERE IDENTIFIER = :glId ORDER BY IDENTIFIER FETCH FIRST 51 ROWS ONLY"),
            Map.entry("LEDGER", "SELECT IDENTIFIER, LEDGER_CODE, LEGAL_ENTITY_REFERENCE, LEDGER_STATE FROM LGR.LEDGERS WHERE LEDGER_CODE = :ledgerCode AND LEGAL_ENTITY_REFERENCE = :legalEntityReference ORDER BY IDENTIFIER FETCH FIRST 51 ROWS ONLY"),
            Map.entry("BINDING", "SELECT IDENTIFIER, SOURCE_DOMAIN, SOURCE_ACCOUNT_REFERENCE, ACCOUNT_ROLE, POSITION_ACCOUNT_REFERENCE, ASSET_CODE, " + UTC_FROM + ", " + UTC_UNTIL + " FROM LGR.ACCOUNT_BINDINGS WHERE SOURCE_DOMAIN = :sourceDomain AND SOURCE_ACCOUNT_REFERENCE = :sourceReference AND ACCOUNT_ROLE = :role AND ASSET_CODE = :assetCode ORDER BY IDENTIFIER FETCH FIRST 51 ROWS ONLY"),
            Map.entry("POSITION", "SELECT IDENTIFIER, LEDGER_IDENTIFIER, POSITION_ACCOUNT_CODE, ASSET_CODE, ACCOUNT_STATE, ALLOW_NEGATIVE_BALANCE FROM LGR.POSITION_ACCOUNTS WHERE LEDGER_IDENTIFIER = :ledgerId AND POSITION_ACCOUNT_CODE = :positionCode AND ASSET_CODE = :assetCode ORDER BY IDENTIFIER FETCH FIRST 51 ROWS ONLY")
    );

    private final NamedParameterJdbcTemplate jdbc;

    public OraclePostingConfigurationRepository(NamedParameterJdbcTemplate jdbc) { this.jdbc = jdbc; }

    @Override public Long count(String qualifiedTable) {
        if (!PostingReadinessCatalog.CONFIGURATION_TABLES.contains(qualifiedTable)) {
            throw new IllegalArgumentException("Unknown configuration table");
        }
        return jdbc.queryForObject("SELECT COUNT(*) FROM " + qualifiedTable, Map.of(), Long.class);
    }

    @Override public List<Map<String, Object>> select(String query, Map<String, ?> parameters) {
        String sql = QUERIES.get(query);
        if (sql == null) throw new IllegalArgumentException("Unknown fixed read query");
        return jdbc.queryForList(sql, parameters);
    }

    // Exposed for source verification, not for client-controlled SQL generation.
    public static List<String> fixedQueryNames() { return QUERIES.keySet().stream().sorted().toList(); }
}
